// src/components/Admin/AddProduct.js
import React, { useState, useRef } from 'react';
import './AddProduct.css';

function AddProduct({ addProduct }) {
  const fileInputRef = useRef(null); 
  
  const [formData, setFormData] = useState({
    productName: '', // Changed to productName for clarity
    price: '',
    productCategory: '', // Changed to productCategory
    productDescription: '', // Changed to productDescription
    // Removed averagePreparationTime, stock, and image URL field to match Image 1
    // Image data will be handled by the file input directly
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    // Simplified validation to match fields present in Image 1
    if (formData.productName && formData.price && formData.productCategory && formData.productDescription) {
      addProduct({
        name: formData.productName, // Map to 'name' for consistency with `addProduct` prop
        price: parseFloat(formData.price),
        category: formData.productCategory, // Map to 'category'
        description: formData.productDescription, // Map to 'description'
        // Hardcode a default image for now, as file upload handling is complex
        image: 'https://via.placeholder.com/150/EEEEEE/808080?text=Product+Image'
        // In a real app, you'd process the fileInputRef.current.files[0] here
      });
      
      setFormData({
        productName: '',
        price: '',
        productCategory: '',
        productDescription: '',
      });
      
      alert('Product added successfully!');
    } else {
      alert('Please fill in all required fields.');
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };
  
  const handleImageClick = () => {
      fileInputRef.current.click();
  };
  
  // You would typically have an onChange handler here for the file input
  // const handleFileChange = (e) => {
  //   const file = e.target.files[0];
  //   if (file) {
  //     // Handle file upload, e.g., display a preview, upload to server etc.
  //     console.log('Selected file:', file.name);
  //   }
  // };

  // This function would be called by the "Add Another Product" button
  const handleAddAnotherProduct = () => {
    // For now, it just clears the form, simulating adding a new product
    setFormData({
      productName: '',
      price: '',
      productCategory: '',
      productDescription: '',
    });
    alert('Form cleared for another product!');
  };

  return (
    // Removed the duplicate <h1>Add New Product</h1> here
    <div className="add-product-container">

      <form onSubmit={handleSubmit} className="product-form">
        <h1>Add a Product</h1> {/* Main title for the form panel */}
        <p className="form-subtitle">Create and add your product to the menu</p>
        
        <div className="form-grid">
            
            {/* LEFT COLUMN: Image Placeholder (Clickable) */}
            <div className="image-column">
                <div 
                    className="image-placeholder-box"
                    onClick={handleImageClick}
                >
                    <span>+ Add Image</span>
                    
                    {/* Hidden file input, connected via ref */}
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        style={{ display: 'none' }} 
                        accept="image/*"
                        // onChange={handleFileChange} // Uncomment in a real app
                    />
                </div>
            </div>

            {/* RIGHT COLUMN: Form Fields, arranged as in Image 1 */}
            <div className="fields-column">
                
                {/* Product name and Price (Side by Side) */}
                <div className="input-row">
                    <div className="form-group half-width">
                        <label>Product name</label>
                        <input type="text" name="productName" value={formData.productName} onChange={handleChange} />
                    </div>
                    <div className="form-group half-width">
                        <label>Price</label>
                        <input type="number" name="price" value={formData.price} onChange={handleChange} />
                    </div>
                </div>

                {/* Product Category (Full Width) */}
                <div className="form-group full-width">
                    <label>Product Category</label>
                    <input type="text" name="productCategory" value={formData.productCategory} onChange={handleChange} />
                    {/* NOTE: If you want a dropdown for category like before, change this input to a select */}
                </div>
                
                {/* Product Description (Full Width - Textarea like appearance) */}
                <div className="form-group full-width">
                    <label>Product Description</label>
                    {/* Changed to textarea for multi-line description, or keep input for single line */}
                    <textarea 
                        name="productDescription" 
                        value={formData.productDescription} 
                        onChange={handleChange} 
                        rows="4" // Give it some height
                    ></textarea>
                </div>
            </div>
        </div>
        
        {/* ADD ANOTHER PRODUCT BUTTON - Added back as per Image 1 */}
        <button type="button" className="add-another-btn" onClick={handleAddAnotherProduct}>
            + Add Another Product
        </button>

        {/* Form Actions Row (Cancel/Save) */}
        <div className="form-actions-row">
            <button type="button" className="action-btn cancel-btn">Cancel</button>
            <button type="submit" className="action-btn submit-btn">Save</button>
        </div>

      </form>
    </div>
  );
}

export default AddProduct;
